    q("mx_042","Presupuestos del anio actual por provincia","Que provincias tienen presupuestos este anio?","COUNT de DOCCAB TIPO=0 del anio actual por provincia del cliente.","SELECT COALESCE(C.CP,'Sin provincia') AS PROVINCIA, COUNT(*) AS N_PRESUPUESTOS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=0 AND SUBSTR(D.FECHA,1,4)=strftime('%Y','now') GROUP BY C.CP ORDER BY N_PRESUPUESTOS DESC LIMIT 20","Marketing","Comercial","Geografico","Medio","",""),
    q("mx_043","Presupuestos del trimestre actual por provincia","Que provincias tienen presupuestos en los ultimos 3 meses?","COUNT de DOCCAB TIPO=0 con FECHA>=date('now','-90 days') por provincia del cliente.","SELECT COALESCE(C.CP,'Sin provincia') AS PROVINCIA, COUNT(*) AS N_PRESUPUESTOS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=0 AND D.FECHA>=date('now','-90 days') GROUP BY C.CP ORDER BY N_PRESUPUESTOS DESC LIMIT 20","Marketing","Comercial","Geografico","Medio","",""),
    q("mx_044","Presupuestos del mes actual por codigo postal","Que codigos postales tienen presupuestos este mes?","COUNT de DOCCAB TIPO=0 del mes actual por codigo postal del cliente.","SELECT COALESCE(C.CP,'Sin CP') AS CP, COUNT(*) AS N_PRESUPUESTOS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=0 AND SUBSTR(D.FECHA,1,7)=strftime('%Y-%m','now') GROUP BY C.CP ORDER BY N_PRESUPUESTOS DESC LIMIT 20","Marketing","Comercial","Geografico","Medio","",""),
    q("mx_045","Presupuestos del anio actual por codigo postal","Que codigos postales tienen presupuestos este anio?","COUNT de DOCCAB TIPO=0 del anio actual por codigo postal del cliente.","SELECT COALESCE(C.CP,'Sin CP') AS CP, COUNT(*) AS N_PRESUPUESTOS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=0 AND SUBSTR(D.FECHA,1,4)=strftime('%Y','now') GROUP BY C.CP ORDER BY N_PRESUPUESTOS DESC LIMIT 20","Marketing","Comercial","Geografico","Medio","",""),
    q("mx_046","Presupuestos del trimestre actual por codigo postal","Que codigos postales tienen presupuestos en los ultimos 3 meses?","COUNT de DOCCAB TIPO=0 con FECHA>=date('now','-90 days') por codigo postal del cliente.","SELECT COALESCE(C.CP,'Sin CP') AS CP, COUNT(*) AS N_PRESUPUESTOS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=0 AND D.FECHA>=date('now','-90 days') GROUP BY C.CP ORDER BY N_PRESUPUESTOS DESC LIMIT 20","Marketing","Comercial","Geografico","Medio","",""),
    q("mx_047","Presupuestos por anio y mes (tabla cruzada)","Como evoluciona la generacion de presupuestos mes a mes en cada anio?","COUNT de DOCCAB TIPO=0 por anio y mes.","SELECT SUBSTR(FECHA,1,4) AS ANIO, CAST(SUBSTR(FECHA,6,2) AS INTEGER) AS MES, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), CAST(SUBSTR(FECHA,6,2) AS INTEGER) ORDER BY ANIO DESC, MES ASC LIMIT 60","Marketing","Comercial","KPI","Alto","",""),
    q("mx_048","Presupuestos por anio y agente (tabla cruzada)","Como evoluciona la carga de presupuestos por agente en cada anio?","COUNT de DOCCAB TIPO=0 por anio y agente.","SELECT SUBSTR(FECHA,1,4) AS ANIO, COALESCE(CAST(CODAGENTE AS TEXT),'Sin agente') AS AGENTE, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL AND CODAGENTE>0 GROUP BY SUBSTR(FECHA,1,4), CODAGENTE ORDER BY ANIO DESC, N_PRESUPUESTOS DESC LIMIT 40","Marketing","Comercial","KPI","Alto","",""),
    q("mx_049","Presupuestos por anio y cliente (tabla cruzada)","Como evoluciona la generacion de presupuestos por cliente en cada anio?","COUNT de DOCCAB TIPO=0 por anio y cliente.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, "+_C+" AS CLIENTE, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=0 AND D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), D.CODCLIENTE ORDER BY ANIO DESC, N_PRESUPUESTOS DESC LIMIT 60","Marketing","Comercial","Cliente","Alto","",""),
    q("mx_050","Presupuestos por anio y articulo (tabla cruzada)","Como evoluciona la aparicion de articulos en presupuestos en cada anio?","COUNT de DOCLIN JOIN DOCCAB TIPO=0 por anio y articulo.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, "+_A+" AS ARTICULO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_PRESUPUESTOS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=0 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO WHERE D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), L.CODARTICULO ORDER BY ANIO DESC, N_PRESUPUESTOS DESC LIMIT 60","Marketing","Comercial","Producto","Alto","",""),
    q("mx_051","Presupuestos por anio y familia (tabla cruzada)","Como evoluciona la aparicion de familias en presupuestos en cada anio?","COUNT de DOCLIN JOIN DOCCAB TIPO=0 por anio y familia.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, COALESCE(F.NOMBRE,'Sin familia') AS FAMILIA, COUNT(DISTINCT L.CODDOCUMENTO) AS N_PRESUPUESTOS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=0 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN FAMILIA F ON A.CODFAMILIA=F.CODIGO WHERE D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), A.CODFAMILIA ORDER BY ANIO DESC, N_PRESUPUESTOS DESC LIMIT 40","Marketing","Comercial","Producto","Alto","",""),
    q("mx_052","Presupuestos por anio y provincia (tabla cruzada)","Como evoluciona la distribucion provincial de presupuestos en cada anio?","COUNT de DOCCAB TIPO=0 por anio y provincia del cliente.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, COALESCE(C.CP,'Sin provincia') AS PROVINCIA, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=0 AND D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), C.CP ORDER BY ANIO DESC, N_PRESUPUESTOS DESC LIMIT 40","Marketing","Comercial","Geografico","Medio","",""),
    q("mx_053","Presupuestos por anio y codigo postal (tabla cruzada)","Como evoluciona la distribucion geografica de presupuestos en cada anio?","COUNT de DOCCAB TIPO=0 por anio y codigo postal del cliente.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, COALESCE(C.CP,'Sin CP') AS CP, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=0 AND D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), C.CP ORDER BY ANIO DESC, N_PRESUPUESTOS DESC LIMIT 40","Marketing","Comercial","Geografico","Medio","",""),
    q("mx_054","Presupuestos por anio y rango de importe (tabla cruzada)","Como evoluciona la distribucion de presupuestos por importe en cada anio?","COUNT de DOCCAB TIPO=0 por anio y rango de importe.","SELECT SUBSTR(FECHA,1,4) AS ANIO, CASE WHEN IMPORTETOTAL=0 THEN 'Cero' WHEN IMPORTETOTAL<100 THEN '<100' WHEN IMPORTETOTAL<500 THEN '100-500' WHEN IMPORTETOTAL<1000 THEN '500-1k' WHEN IMPORTETOTAL<5000 THEN '1k-5k' WHEN IMPORTETOTAL<10000 THEN '5k-10k' ELSE '>10k' END AS RANGO, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), RANGO ORDER BY ANIO DESC, N_PRESUPUESTOS DESC LIMIT 40","Marketing","Comercial","Financiero","Medio","",""),
    q("mx_055","Presupuestos por anio y trimestre (tabla cruzada)","Como evoluciona la generacion de presupuestos trimestre a trimestre en cada anio?","COUNT de DOCCAB TIPO=0 por anio y trimestre.","SELECT SUBSTR(FECHA,1,4) AS ANIO, ((CAST(SUBSTR(FECHA,6,2) AS INTEGER)-1)/3+1) AS TRIMESTRE, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), TRIMESTRE ORDER BY ANIO DESC, TRIMESTRE ASC LIMIT 20","Marketing","Comercial","KPI","Alto","",""),
    q("mx_056","Presupuestos por anio y semestre (tabla cruzada)","Como evoluciona la generacion de presupuestos semestre a semestre en cada anio?","COUNT de DOCCAB TIPO=0 por anio y semestre.","SELECT SUBSTR(FECHA,1,4) AS ANIO, CASE WHEN CAST(SUBSTR(FECHA,6,2) AS INTEGER)<=6 THEN 1 ELSE 2 END AS SEMESTRE, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), SEMESTRE ORDER BY ANIO DESC, SEMESTRE ASC LIMIT 20","Marketing","Comercial","KPI","Medio","",""),
    q("mx_057","Presupuestos por anio y dia de la semana (tabla cruzada)","Como evoluciona la generacion de presupuestos por dia de la semana en cada anio?","COUNT de DOCCAB TIPO=0 por anio y dia de la semana.","SELECT SUBSTR(FECHA,1,4) AS ANIO, CASE CAST(strftime('%w',FECHA) AS INTEGER) WHEN 0 THEN 'Domingo' WHEN 1 THEN 'Lunes' WHEN 2 THEN 'Martes' WHEN 3 THEN 'Miercoles' WHEN 4 THEN 'Jueves' WHEN 5 THEN 'Viernes' ELSE 'Sabado' END AS DIA, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), strftime('%w',FECHA) ORDER BY ANIO DESC, N_PRESUPUESTOS DESC LIMIT 40","Marketing","Comercial","Operacional","Bajo","",""),
    q("mx_058","Presupuestos por anio y hora del dia (tabla cruzada)","Como evoluciona la generacion de presupuestos por hora del dia en cada anio?","COUNT de DOCCAB TIPO=0 por anio y hora del dia.","SELECT SUBSTR(FECHA,1,4) AS ANIO, CAST(strftime('%H',FECHA) AS INTEGER) AS HORA, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), HORA ORDER BY ANIO DESC, HORA ASC LIMIT 60","Marketing","Comercial","Operacional","Bajo","",""),
    q("mx_059","Presupuestos por anio y dia del mes (tabla cruzada)","Como evoluciona la generacion de presupuestos por dia del mes en cada anio?","COUNT de DOCCAB TIPO=0 por anio y dia del mes.","SELECT SUBSTR(FECHA,1,4) AS ANIO, CAST(strftime('%d',FECHA) AS INTEGER) AS DIA_MES, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), DIA_MES ORDER BY ANIO DESC, DIA_MES ASC LIMIT 60","Marketing","Comercial","Operacional","Bajo","",""),
    q("mx_060","Presupuestos por anio y semana del anio (tabla cruzada)","Como evoluciona la generacion de presupuestos por semana del anio en cada anio?","COUNT de DOCCAB TIPO=0 por anio y semana del anio.","SELECT SUBSTR(FECHA,1,4) AS ANIO, CAST(strftime('%W',FECHA) AS INTEGER) AS SEMANA, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), SEMANA ORDER BY ANIO DESC, SEMANA ASC LIMIT 60","Marketing","Comercial","Operacional","Bajo","",""),
    q("mx_061","Presupuestos por anio y mes del anio (estacionalidad)","Que meses del anio se generan mas presupuestos historicamente?","COUNT de DOCCAB TIPO=0 por mes del anio (1-12) en toda la historia.","SELECT CAST(strftime('%m',FECHA) AS INTEGER) AS MES_NUM, CASE CAST(strftime('%m',FECHA) AS INTEGER) WHEN 1 THEN 'Enero' WHEN 2 THEN 'Febrero' WHEN 3 THEN 'Marzo' WHEN 4 THEN 'Abril' WHEN 5 THEN 'Mayo' WHEN 6 THEN 'Junio' WHEN 7 THEN 'Julio' WHEN 8 THEN 'Agosto' WHEN 9 THEN 'Septiembre' WHEN 10 THEN 'Octubre' WHEN 11 THEN 'Noviembre' ELSE 'Diciembre' END AS MES_NOMBRE, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY MES_NUM ORDER BY N_PRESUPUESTOS DESC","Marketing","Comercial","Operacional","Medio","",""),
    q("mx_062","Presupuestos por anio y trimestre del anio (estacionalidad)","Que trimestres del anio se generan mas presupuestos historicamente?","COUNT de DOCCAB TIPO=0 por trimestre del anio (1-4) en toda la historia.","SELECT ((CAST(SUBSTR(FECHA,6,2) AS INTEGER)-1)/3+1) AS TRIMESTRE, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY TRIMESTRE ORDER BY N_PRESUPUESTOS DESC","Marketing","Comercial","Operacional","Medio","",""),
    q("mx_063","Presupuestos por anio y semestre del anio (estacionalidad)","Que semestres del anio se generan mas presupuestos historicamente?","COUNT de DOCCAB TIPO=0 por semestre del anio (1-2) en toda la historia.","SELECT CASE WHEN CAST(SUBSTR(FECHA,6,2) AS INTEGER)<=6 THEN 1 ELSE 2 END AS SEMESTRE, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY SEMESTRE ORDER BY N_PRESUPUESTOS DESC","Marketing","Comercial","Operacional","Bajo","",""),
    q("mx_064","Presupuestos por anio y dia de la semana (estacionalidad)","Que dias de la semana se generan mas presupuestos historicamente?","COUNT de DOCCAB TIPO=0 por dia de la semana en toda la historia.","SELECT CASE CAST(strftime('%w',FECHA) AS INTEGER) WHEN 0 THEN 'Domingo' WHEN 1 THEN 'Lunes' WHEN 2 THEN 'Martes' WHEN 3 THEN 'Miercoles' WHEN 4 THEN 'Jueves' WHEN 5 THEN 'Viernes' ELSE 'Sabado' END AS DIA, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY strftime('%w',FECHA) ORDER BY N_PRESUPUESTOS DESC","Marketing","Comercial","Operacional","Bajo","",""),
    q("mx_065","Presupuestos por anio y hora del dia (estacionalidad)","A que horas del dia se generan mas presupuestos historicamente?","COUNT de DOCCAB TIPO=0 por hora del dia en toda la historia.","SELECT CAST(strftime('%H',FECHA) AS INTEGER) AS HORA, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY HORA ORDER BY HORA","Marketing","Comercial","Operacional","Bajo","",""),
    q("mx_066","Presupuestos por anio y dia del mes (estacionalidad)","Que dias del mes se generan mas presupuestos historicamente?","COUNT de DOCCAB TIPO=0 por dia del mes en toda la historia.","SELECT CAST(strftime('%d',FECHA) AS INTEGER) AS DIA_MES, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY DIA_MES ORDER BY N_PRESUPUESTOS DESC LIMIT 31","Marketing","Comercial","Operacional","Bajo","",""),
    q("mx_067","Presupuestos por anio y semana del anio (estacionalidad)","Que semanas del anio se generan mas presupuestos historicamente?","COUNT de DOCCAB TIPO=0 por semana del anio en toda la historia.","SELECT CAST(strftime('%W',FECHA) AS INTEGER) AS SEMANA, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY SEMANA ORDER BY N_PRESUPUESTOS DESC LIMIT 52","Marketing","Comercial","Operacional","Bajo","",""),
    q("mx_068","Presupuestos por anio y agente (estacionalidad)","Como se distribuyen los presupuestos por agente historicamente?","COUNT de DOCCAB TIPO=0 por agente en toda la historia.","SELECT COALESCE(CAST(CODAGENTE AS TEXT),'Sin agente') AS AGENTE, COUNT(*) AS N_PRESUPUESTOS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE TIPO=0 AND CODAGENTE>0 GROUP BY CODAGENTE ORDER BY N_PRESUPUESTOS DESC LIMIT 20","Marketing","Comercial","KPI","Alto","",""),
    q("mx_069","Presupuestos por anio y cliente (estacionalidad)","Como se distribuyen los presupuestos por cliente historicamente?","COUNT de DOCCAB TIPO=0 por cliente en toda la historia.","SELECT "+_C+" AS CLIENTE, COUNT(*) AS N_PRESUPUESTOS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=0 GROUP BY D.CODCLIENTE ORDER BY N_PRESUPUESTOS DESC LIMIT 20","Marketing","Comercial","Cliente","Alto","",""),
    q("mx_070","Presupuestos por anio y articulo (estacionalidad)","Como se distribuyen los presupuestos por articulo historicamente?","COUNT de DOCLIN JOIN DOCCAB TIPO=0 por articulo en toda la historia.","SELECT "+_A+" AS ARTICULO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_PRESUPUESTOS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL)),2) AS IMPORTE FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=0 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO GROUP BY L.CODARTICULO ORDER BY N_PRESUPUESTOS DESC LIMIT 20","Marketing","Comercial","Producto","Alto","",""),
    q("mx_071","Presupuestos por anio y familia (estacionalidad)","Como se distribuyen los presupuestos por familia historicamente?","COUNT de DOCLIN JOIN DOCCAB TIPO=0 por familia en toda la historia.","SELECT COALESCE(F.NOMBRE,'Sin familia') AS FAMILIA, COUNT(DISTINCT L.CODDOCUMENTO) AS N_PRESUPUESTOS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL)),2) AS IMPORTE FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=0 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN FAMILIA F ON A.CODFAMILIA=F.CODIGO GROUP BY A.CODFAMILIA ORDER BY N_PRESUPUESTOS DESC LIMIT 20","Marketing","Comercial","Producto","Alto","",""),
    q("mx_072","Presupuestos por anio y provincia (estacionalidad)","Como se distribuyen los presupuestos por provincia historicamente?","COUNT de DOCCAB TIPO=0 por provincia del cliente en toda la historia.","SELECT COALESCE(C.CP,'Sin provincia') AS PROVINCIA, COUNT(*) AS N_PRESUPUESTOS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=0 GROUP BY C.CP ORDER BY N_PRESUPUESTOS DESC LIMIT 20","Marketing","Comercial","Geografico","Medio","",""),
    q("mx_073","Presupuestos por anio y codigo postal (estacionalidad)","Como se distribuyen los presupuestos por codigo postal historicamente?","COUNT de DOCCAB TIPO=0 por codigo postal del cliente en toda la historia.","SELECT COALESCE(C.CP,'Sin CP') AS CP, COUNT(*) AS N_PRESUPUESTOS, ROUND(SUM(D.IMPORTETOTAL),2) AS TOTAL FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=0 GROUP BY C.CP ORDER BY N_PRESUPUESTOS DESC LIMIT 20","Marketing","Comercial","Geografico","Medio","",""),
    q("mx_074","Presupuestos por anio y rango de importe (estacionalidad)","Como se distribuyen los presupuestos por importe historicamente?","COUNT de DOCCAB TIPO=0 por rango de importe en toda la historia.","SELECT CASE WHEN IMPORTETOTAL=0 THEN 'Cero' WHEN IMPORTETOTAL<100 THEN '<100' WHEN IMPORTETOTAL<500 THEN '100-500' WHEN IMPORTETOTAL<1000 THEN '500-1k' WHEN IMPORTETOTAL<5000 THEN '1k-5k' WHEN IMPORTETOTAL<10000 THEN '5k-10k' ELSE '>10k' END AS RANGO, COUNT(*) AS N_PRESUPUESTOS, ROUND(SUM(IMPORTETOTAL),2) AS TOTAL FROM DOCCAB WHERE TIPO=0 GROUP BY RANGO ORDER BY N_PRESUPUESTOS DESC","Marketing","Comercial","Financiero","Medio","",""),
    q("mx_075","Presupuestos por anio y numero de lineas (estacionalidad)","Como se distribuyen los presupuestos por numero de lineas historicamente?","COUNT de DOCCAB TIPO=0 por rango de lineas en toda la historia.","SELECT CASE WHEN N_LINEAS=0 THEN 'Sin lineas' WHEN N_LINEAS=1 THEN '1 linea' WHEN N_LINEAS<=3 THEN '2-3 lineas' WHEN N_LINEAS<=5 THEN '4-5 lineas' WHEN N_LINEAS<=10 THEN '6-10 lineas' ELSE '>10 lineas' END AS RANGO, COUNT(*) AS N_PRESUPUESTOS FROM (SELECT D.CODIGO, COUNT(L.CODARTICULO) AS N_LINEAS FROM DOCCAB D LEFT JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO WHERE D.TIPO=0 GROUP BY D.CODIGO) GROUP BY RANGO ORDER BY N_PRESUPUESTOS DESC","Marketing","Comercial","Operacional","Bajo","",""),
    q("mx_076","Presupuestos por anio y ticket medio (estacionalidad)","Como evoluciona el ticket medio de presupuesto en cada anio?","AVG(IMPORTETOTAL) de DOCCAB TIPO=0 por anio en toda la historia.","SELECT SUBSTR(FECHA,1,4) AS ANIO, ROUND(AVG(IMPORTETOTAL),2) AS TICKET_MEDIO, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4) ORDER BY ANIO DESC","Marketing","Comercial","KPI","Medio","",""),
    q("mx_077","Presupuestos por anio y ticket medio por agente (estacionalidad)","Como evoluciona el ticket medio de presupuesto por agente en cada anio?","AVG(IMPORTETOTAL) de DOCCAB TIPO=0 por anio y agente en toda la historia.","SELECT SUBSTR(FECHA,1,4) AS ANIO, COALESCE(CAST(CODAGENTE AS TEXT),'Sin agente') AS AGENTE, ROUND(AVG(IMPORTETOTAL),2) AS TICKET_MEDIO, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL AND CODAGENTE>0 GROUP BY SUBSTR(FECHA,1,4), CODAGENTE ORDER BY ANIO DESC, TICKET_MEDIO DESC LIMIT 40","Marketing","Comercial","KPI","Medio","",""),
    q("mx_078","Presupuestos por anio y ticket medio por cliente (estacionalidad)","Como evoluciona el ticket medio de presupuesto por cliente en cada anio?","AVG(IMPORTETOTAL) de DOCCAB TIPO=0 por anio y cliente en toda la historia.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, "+_C+" AS CLIENTE, ROUND(AVG(D.IMPORTETOTAL),2) AS TICKET_MEDIO, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=0 AND D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), D.CODCLIENTE ORDER BY ANIO DESC, TICKET_MEDIO DESC LIMIT 60","Marketing","Comercial","Cliente","Medio","",""),
    q("mx_079","Presupuestos por anio y ticket medio por articulo (estacionalidad)","Como evoluciona el ticket medio de presupuesto por articulo en cada anio?","AVG(IMPORTETOTAL) de DOCCAB TIPO=0 por anio y articulo en toda la historia.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, "+_A+" AS ARTICULO, ROUND(AVG(D.IMPORTETOTAL),2) AS TICKET_MEDIO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_PRESUPUESTOS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=0 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO WHERE D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), L.CODARTICULO ORDER BY ANIO DESC, TICKET_MEDIO DESC LIMIT 60","Marketing","Comercial","Producto","Medio","",""),
    q("mx_080","Presupuestos por anio y ticket medio por familia (estacionalidad)","Como evoluciona el ticket medio de presupuesto por familia en cada anio?","AVG(IMPORTETOTAL) de DOCCAB TIPO=0 por anio y familia en toda la historia.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, COALESCE(F.NOMBRE,'Sin familia') AS FAMILIA, ROUND(AVG(D.IMPORTETOTAL),2) AS TICKET_MEDIO, COUNT(DISTINCT L.CODDOCUMENTO) AS N_PRESUPUESTOS FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=0 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN FAMILIA F ON A.CODFAMILIA=F.CODIGO WHERE D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), A.CODFAMILIA ORDER BY ANIO DESC, TICKET_MEDIO DESC LIMIT 40","Marketing","Comercial","Producto","Medio","",""),
    q("mx_081","Presupuestos por anio y ticket medio por provincia (estacionalidad)","Como evoluciona el ticket medio de presupuesto por provincia en cada anio?","AVG(IMPORTETOTAL) de DOCCAB TIPO=0 por anio y provincia del cliente en toda la historia.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, COALESCE(C.CP,'Sin provincia') AS PROVINCIA, ROUND(AVG(D.IMPORTETOTAL),2) AS TICKET_MEDIO, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=0 AND D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), C.CP ORDER BY ANIO DESC, TICKET_MEDIO DESC LIMIT 40","Marketing","Comercial","Geografico","Bajo","",""),
    q("mx_082","Presupuestos por anio y ticket medio por codigo postal (estacionalidad)","Como evoluciona el ticket medio de presupuesto por codigo postal en cada anio?","AVG(IMPORTETOTAL) de DOCCAB TIPO=0 por anio y codigo postal del cliente en toda la historia.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, COALESCE(C.CP,'Sin CP') AS CP, ROUND(AVG(D.IMPORTETOTAL),2) AS TICKET_MEDIO, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB D LEFT JOIN CLIENTE C ON D.CODCLIENTE=C.CODIGO WHERE D.TIPO=0 AND D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), C.CP ORDER BY ANIO DESC, TICKET_MEDIO DESC LIMIT 40","Marketing","Comercial","Geografico","Bajo","",""),
    q("mx_083","Presupuestos por anio y ticket medio por rango de importe (estacionalidad)","Como evoluciona la distribucion de presupuestos por importe en cada anio?","COUNT de DOCCAB TIPO=0 por anio y rango de importe en toda la historia.","SELECT SUBSTR(FECHA,1,4) AS ANIO, CASE WHEN IMPORTETOTAL=0 THEN 'Cero' WHEN IMPORTETOTAL<100 THEN '<100' WHEN IMPORTETOTAL<500 THEN '100-500' WHEN IMPORTETOTAL<1000 THEN '500-1k' WHEN IMPORTETOTAL<5000 THEN '1k-5k' WHEN IMPORTETOTAL<10000 THEN '5k-10k' ELSE '>10k' END AS RANGO, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), RANGO ORDER BY ANIO DESC, N_PRESUPUESTOS DESC LIMIT 40","Marketing","Comercial","Financiero","Medio","",""),
    q("mx_084","Presupuestos por anio y ticket medio por numero de lineas (estacionalidad)","Como evoluciona la distribucion de presupuestos por numero de lineas en cada anio?","COUNT de DOCCAB TIPO=0 por anio y rango de lineas en toda la historia.","SELECT SUBSTR(D.FECHA,1,4) AS ANIO, CASE WHEN COUNT(L.CODARTICULO)=0 THEN 'Sin lineas' WHEN COUNT(L.CODARTICULO)=1 THEN '1 linea' WHEN COUNT(L.CODARTICULO)<=3 THEN '2-3 lineas' WHEN COUNT(L.CODARTICULO)<=5 THEN '4-5 lineas' ELSE '>5 lineas' END AS RANGO_LINEAS, COUNT(DISTINCT D.CODIGO) AS N_PRESUPUESTOS FROM DOCCAB D LEFT JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO WHERE D.TIPO=0 AND D.FECHA IS NOT NULL GROUP BY SUBSTR(D.FECHA,1,4), D.CODIGO ORDER BY ANIO DESC LIMIT 40","Marketing","Comercial","Operacional","Bajo","",""),
    q("mx_085","Presupuestos por anio y ticket medio por dia de la semana (estacionalidad)","Como evoluciona la generacion de presupuestos por dia de la semana en cada anio?","COUNT de DOCCAB TIPO=0 por anio y dia de la semana en toda la historia.","SELECT SUBSTR(FECHA,1,4) AS ANIO, CASE CAST(strftime('%w',FECHA) AS INTEGER) WHEN 0 THEN 'Domingo' WHEN 1 THEN 'Lunes' WHEN 2 THEN 'Martes' WHEN 3 THEN 'Miercoles' WHEN 4 THEN 'Jueves' WHEN 5 THEN 'Viernes' ELSE 'Sabado' END AS DIA, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), strftime('%w',FECHA) ORDER BY ANIO DESC, N_PRESUPUESTOS DESC LIMIT 40","Marketing","Comercial","Operacional","Bajo","",""),
    q("mx_086","Presupuestos por anio y ticket medio por hora del dia (estacionalidad)","Como evoluciona la generacion de presupuestos por hora del dia en cada anio?","COUNT de DOCCAB TIPO=0 por anio y hora del dia en toda la historia.","SELECT SUBSTR(FECHA,1,4) AS ANIO, CAST(strftime('%H',FECHA) AS INTEGER) AS HORA, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), HORA ORDER BY ANIO DESC, HORA ASC LIMIT 60","Marketing","Comercial","Operacional","Bajo","",""),
    q("mx_087","Presupuestos por anio y ticket medio por dia del mes (estacionalidad)","Como evoluciona la generacion de presupuestos por dia del mes en cada anio?","COUNT de DOCCAB TIPO=0 por anio y dia del mes en toda la historia.","SELECT SUBSTR(FECHA,1,4) AS ANIO, CAST(strftime('%d',FECHA) AS INTEGER) AS DIA_MES, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), DIA_MES ORDER BY ANIO DESC, DIA_MES ASC LIMIT 60","Marketing","Comercial","Operacional","Bajo","",""),
    q("mx_088","Presupuestos por anio y ticket medio por semana del anio (estacionalidad)","Como evoluciona la generacion de presupuestos por semana del anio en cada anio?","COUNT de DOCCAB TIPO=0 por anio y semana del anio en toda la historia.","SELECT SUBSTR(FECHA,1,4) AS ANIO, CAST(strftime('%W',FECHA) AS INTEGER) AS SEMANA, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), SEMANA ORDER BY ANIO DESC, SEMANA ASC LIMIT 60","Marketing","Comercial","Operacional","Bajo","",""),
    q("mx_089","Presupuestos por anio y ticket medio por mes del anio (estacionalidad)","Como evoluciona la generacion de presupuestos por mes del anio en cada anio?","COUNT de DOCCAB TIPO=0 por anio y mes del anio (1-12) en toda la historia.","SELECT SUBSTR(FECHA,1,4) AS ANIO, CAST(strftime('%m',FECHA) AS INTEGER) AS MES_NUM, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), MES_NUM ORDER BY ANIO DESC, MES_NUM ASC LIMIT 60","Marketing","Comercial","Operacional","Bajo","",""),
    q("mx_090","Presupuestos por anio y ticket medio por trimestre del anio (estacionalidad)","Como evoluciona la generacion de presupuestos por trimestre del anio en cada anio?","COUNT de DOCCAB TIPO=0 por anio y trimestre del anio (1-4) en toda la historia.","SELECT SUBSTR(FECHA,1,4) AS ANIO, ((CAST(SUBSTR(FECHA,6,2) AS INTEGER)-1)/3+1) AS TRIMESTRE, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), TRIMESTRE ORDER BY ANIO DESC, TRIMESTRE ASC LIMIT 20","Marketing","Comercial","Operacional","Bajo","",""),
    q("mx_091","Presupuestos por anio y ticket medio por semestre del anio (estacionalidad)","Como evoluciona la generacion de presupuestos por semestre del anio en cada anio?","COUNT de DOCCAB TIPO=0 por anio y semestre del anio (1-2) en toda la historia.","SELECT SUBSTR(FECHA,1,4) AS ANIO, CASE WHEN CAST(SUBSTR(FECHA,6,2) AS INTEGER)<=6 THEN 1 ELSE 2 END AS SEMESTRE, COUNT(*) AS N_PRESUPUESTOS FROM DOCCAB WHERE TIPO=0 AND FECHA IS NOT NULL GROUP BY SUBSTR(FECHA,1,4), SEMESTRE ORDER BY ANIO DESC, SEMESTRE ASC LIMIT 20","Marketing","Comercial","Operacional","Bajo","",""),
    q("mx_092","Presupuestos por anio y ticket medio por proveedor (estacionalidad)","Como se distribuyen los presupuestos por proveedor historicamente?","COUNT de DOCLIN JOIN DOCCAB TIPO=0 por proveedor en toda la historia.","SELECT COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, COUNT(DISTINCT L.CODDOCUMENTO) AS N_PRESUPUESTOS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL)),2) AS IMPORTE FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=0 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO GROUP BY A.PROVEEDDEFECTO ORDER BY N_PRESUPUESTOS DESC LIMIT 20","Marketing","Comercial","Proveedor","Medio","",""),
    q("mx_093","Presupuestos por anio y ticket medio por proveedor en el anio actual (estacionalidad)","Como se distribuyen los presupuestos por proveedor este anio?","COUNT de DOCLIN JOIN DOCCAB TIPO=0 del anio actual por proveedor.","SELECT COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, COUNT(DISTINCT L.CODDOCUMENTO) AS N_PRESUPUESTOS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL)),2) AS IMPORTE FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=0 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO WHERE SUBSTR(D.FECHA,1,4)=strftime('%Y','now') GROUP BY A.PROVEEDDEFECTO ORDER BY N_PRESUPUESTOS DESC LIMIT 20","Marketing","Comercial","Proveedor","Medio","",""),
    q("mx_094","Presupuestos por anio y ticket medio por proveedor en el mes actual (estacionalidad)","Como se distribuyen los presupuestos por proveedor este mes?","COUNT de DOCLIN JOIN DOCCAB TIPO=0 del mes actual por proveedor.","SELECT COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, COUNT(DISTINCT L.CODDOCUMENTO) AS N_PRESUPUESTOS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL)),2) AS IMPORTE FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=0 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO WHERE SUBSTR(D.FECHA,1,7)=strftime('%Y-%m','now') GROUP BY A.PROVEEDDEFECTO ORDER BY N_PRESUPUESTOS DESC LIMIT 20","Marketing","Comercial","Proveedor","Medio","",""),
    q("mx_095","Presupuestos por anio y ticket medio por proveedor en el trimestre actual (estacionalidad)","Como se distribuyen los presupuestos por proveedor en los ultimos 3 meses?","COUNT de DOCLIN JOIN DOCCAB TIPO=0 con FECHA>=date('now','-90 days') por proveedor.","SELECT COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, COUNT(DISTINCT L.CODDOCUMENTO) AS N_PRESUPUESTOS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL)),2) AS IMPORTE FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=0 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO WHERE D.FECHA>=date('now','-90 days') GROUP BY A.PROVEEDDEFECTO ORDER BY N_PRESUPUESTOS DESC LIMIT 20","Marketing","Comercial","Proveedor","Medio","",""),
    q("mx_096","Presupuestos por anio y ticket medio por proveedor en toda la historia (estacionalidad)","Como se distribuyen los presupuestos por proveedor en toda la historia?","COUNT de DOCLIN JOIN DOCCAB TIPO=0 por proveedor en toda la historia.","SELECT COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, COUNT(DISTINCT L.CODDOCUMENTO) AS N_PRESUPUESTOS, ROUND(SUM(CAST(L.CANTIDAD AS REAL)*CAST(L.PRECIO AS REAL)),2) AS IMPORTE FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=0 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO GROUP BY A.PROVEEDDEFECTO ORDER BY N_PRESUPUESTOS DESC LIMIT 20","Marketing","Comercial","Proveedor","Medio","",""),
    q("mx_097","Presupuestos por anio y ticket medio por proveedor en el anio actual vs anio anterior (estacionalidad)","Como compara la distribucion de presupuestos por proveedor este anio vs el anterior?","COUNT de DOCLIN JOIN DOCCAB TIPO=0 por proveedor en el anio actual vs anio anterior.","SELECT COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, COUNT(DISTINCT CASE WHEN SUBSTR(D.FECHA,1,4)=strftime('%Y','now') THEN L.CODDOCUMENTO END) AS N_ANIO_ACTUAL, COUNT(DISTINCT CASE WHEN SUBSTR(D.FECHA,1,4)=CAST(CAST(strftime('%Y','now') AS INTEGER)-1 AS TEXT) THEN L.CODDOCUMENTO END) AS N_ANIO_ANTERIOR FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=0 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO GROUP BY A.PROVEEDDEFECTO ORDER BY N_ANIO_ACTUAL DESC LIMIT 20","Marketing","Comercial","Proveedor","Medio","",""),
    q("mx_098","Presupuestos por anio y ticket medio por proveedor en el mes actual vs mes anterior (estacionalidad)","Como compara la distribucion de presupuestos por proveedor este mes vs el anterior?","COUNT de DOCLIN JOIN DOCCAB TIPO=0 por proveedor en el mes actual vs mes anterior.","SELECT COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, COUNT(DISTINCT CASE WHEN SUBSTR(D.FECHA,1,7)=strftime('%Y-%m','now') THEN L.CODDOCUMENTO END) AS N_MES_ACTUAL, COUNT(DISTINCT CASE WHEN SUBSTR(D.FECHA,1,7)=strftime('%Y-%m','now','-1 month') THEN L.CODDOCUMENTO END) AS N_MES_ANTERIOR FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=0 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO GROUP BY A.PROVEEDDEFECTO ORDER BY N_MES_ACTUAL DESC LIMIT 20","Marketing","Comercial","Proveedor","Medio","",""),
    q("mx_099","Presupuestos por anio y ticket medio por proveedor en el trimestre actual vs trimestre anterior (estacionalidad)","Como compara la distribucion de presupuestos por proveedor en el trimestre actual vs el anterior?","COUNT de DOCLIN JOIN DOCCAB TIPO=0 por proveedor en el trimestre actual vs anterior.","SELECT COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, COUNT(DISTINCT CASE WHEN D.FECHA>=date('now','-90 days') THEN L.CODDOCUMENTO END) AS N_TRIMESTRE_ACTUAL, COUNT(DISTINCT CASE WHEN D.FECHA>=date('now','-180 days') AND D.FECHA<date('now','-90 days') THEN L.CODDOCUMENTO END) AS N_TRIMESTRE_ANTERIOR FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=0 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO GROUP BY A.PROVEEDDEFECTO ORDER BY N_TRIMESTRE_ACTUAL DESC LIMIT 20","Marketing","Comercial","Proveedor","Medio","",""),
    q("mx_100","Presupuestos por anio y ticket medio por proveedor en los ultimos 6 meses vs 6 meses anteriores (estacionalidad)","Como compara la distribucion de presupuestos por proveedor en los ultimos 6 meses vs los 6 anteriores?","COUNT de DOCLIN JOIN DOCCAB TIPO=0 por proveedor en los ultimos 6 meses vs los 6 anteriores.","SELECT COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, COUNT(DISTINCT CASE WHEN D.FECHA>=date('now','-180 days') THEN L.CODDOCUMENTO END) AS N_6M_ACTUAL, COUNT(DISTINCT CASE WHEN D.FECHA>=date('now','-360 days') AND D.FECHA<date('now','-180 days') THEN L.CODDOCUMENTO END) AS N_6M_ANTERIOR FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=0 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO GROUP BY A.PROVEEDDEFECTO ORDER BY N_6M_ACTUAL DESC LIMIT 20","Marketing","Comercial","Proveedor","Medio","",""),
    q("mx_101","Presupuestos por anio y ticket medio por proveedor en el ultimo anio vs anio anterior (estacionalidad)","Como compara la distribucion de presupuestos por proveedor en el ultimo anio vs el anterior?","COUNT de DOCLIN JOIN DOCCAB TIPO=0 por proveedor en el ultimo anio vs el anterior.","SELECT COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, COUNT(DISTINCT CASE WHEN D.FECHA>=date('now','-365 days') THEN L.CODDOCUMENTO END) AS N_365D_ACTUAL, COUNT(DISTINCT CASE WHEN D.FECHA>=date('now','-730 days') AND D.FECHA<date('now','-365 days') THEN L.CODDOCUMENTO END) AS N_365D_ANTERIOR FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=0 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO GROUP BY A.PROVEEDDEFECTO ORDER BY N_365D_ACTUAL DESC LIMIT 20","Marketing","Comercial","Proveedor","Medio","",""),
    q("mx_102","Presupuestos por anio y ticket medio por proveedor en toda la historia vs anio actual (estacionalidad)","Como compara la distribucion de presupuestos por proveedor en toda la historia vs este anio?","COUNT de DOCLIN JOIN DOCCAB TIPO=0 por proveedor en toda la historia vs este anio.","SELECT COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, COUNT(DISTINCT L.CODDOCUMENTO) AS N_TOTAL, COUNT(DISTINCT CASE WHEN SUBSTR(D.FECHA,1,4)=strftime('%Y','now') THEN L.CODDOCUMENTO END) AS N_ANIO_ACTUAL FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=0 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO GROUP BY A.PROVEEDDEFECTO ORDER BY N_TOTAL DESC LIMIT 20","Marketing","Comercial","Proveedor","Medio","",""),
    q("mx_103","Presupuestos por anio y ticket medio por proveedor en toda la historia vs mes actual (estacionalidad)","Como compara la distribucion de presupuestos por proveedor en toda la historia vs este mes?","COUNT de DOCLIN JOIN DOCCAB TIPO=0 por proveedor en toda la historia vs este mes.","SELECT COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, COUNT(DISTINCT L.CODDOCUMENTO) AS N_TOTAL, COUNT(DISTINCT CASE WHEN SUBSTR(D.FECHA,1,7)=strftime('%Y-%m','now') THEN L.CODDOCUMENTO END) AS N_MES_ACTUAL FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=0 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO GROUP BY A.PROVEEDDEFECTO ORDER BY N_TOTAL DESC LIMIT 20","Marketing","Comercial","Proveedor","Medio","",""),
    q("mx_104","Presupuestos por anio y ticket medio por proveedor en toda la historia vs trimestre actual (estacionalidad)","Como compara la distribucion de presupuestos por proveedor en toda la historia vs el trimestre actual?","COUNT de DOCLIN JOIN DOCCAB TIPO=0 por proveedor en toda la historia vs el trimestre actual.","SELECT COALESCE(P.NOMBRECOMERCIAL,P.RAZONSOCIAL,'Sin proveedor') AS PROVEEDOR, COUNT(DISTINCT L.CODDOCUMENTO) AS N_TOTAL, COUNT(DISTINCT CASE WHEN D.FECHA>=date('now','-90 days') THEN L.CODDOCUMENTO END) AS N_TRIMESTRE_ACTUAL FROM DOCLIN L JOIN DOCCAB D ON L.CODDOCUMENTO=D.CODIGO AND D.TIPO=0 LEFT JOIN ARTICULO A ON L.CODARTICULO=A.CODIGO LEFT JOIN PROVEED P ON A.PROVEEDDEFECTO=P.CODIGO GROUP BY A.PROVEEDDEFECTO ORDER BY N_TOTAL DESC LIMIT 20","Marketing","Comercial","Proveedor","Medio","",""),
