    q("mx_125","Resumen ejecutivo de marketing","Cual es el resumen ejecutivo de los KPIs de marketing mas importantes?","Combina presupuestos, clientes sin conversion, conversion, articulos en presupuestos.","SELECT ROUND((SELECT COUNT(*) FROM DOCCAB WHERE TIPO=0),0) AS TOTAL_PRESUPUESTOS, ROUND((SELECT SUM(IMPORTETOTAL) FROM DOCCAB WHERE TIPO=0),2) AS IMPORTE_TOTAL_PRESUPUESTOS, ROUND((SELECT COUNT(DISTINCT CODCLIENTE) FROM DOCCAB WHERE TIPO=0),0) AS CLIENTES_CON_PRESUPUESTO, ROUND((SELECT COUNT(DISTINCT CODCLIENTE) FROM DOCCAB WHERE TIPO=0 AND CODCLIENTE IN (SELECT DISTINCT CODCLIENTE FROM DOCCAB WHERE TIPO=13 AND CODCLIENTE IS NOT NULL)),0) AS CLIENTES_CONVERTIDOS, ROUND((SELECT COUNT(*) FROM DOCCAB WHERE TIPO=0 AND SUBSTR(FECHA,1,7)=strftime('%Y-%m','now')),0) AS PRESUPUESTOS_MES_ACTUAL","Marketing","Comercial","KPI","Critico","Resumen ejecutivo marketing",""),
